mapper.sql:
e.media_type = (
    SELECT CASE WHEN COUNT(DISTINCT a.media_type) > 1 THEN #{mixedMediaType}
                ELSE MIN(a.media_type) END
    FROM label_asset a WHERE a.entry_id = e.id AND a.deleted = 0
),
e.parse_status = (
    SELECT CASE WHEN SUM(a.parse_status = #{failedStatus}) > 0 THEN #{failedStatus}
                ELSE #{successStatus} END
    FROM label_asset a WHERE a.entry_id = e.id AND a.deleted = 0
),
e.first_asset_id = (
    SELECT a.id FROM label_asset a
    WHERE a.entry_id = e.id AND a.deleted = 0 ORDER BY a.id LIMIT 1
),
e.update_time = NOW()

